#!/usr/bin/env python3
"""Independent mean-field complex DOP853, exact Fraction root profiles and OA branches."""
import argparse,json
from pathlib import Path
from fractions import Fraction as F
from collections import Counter
import numpy as np
from scipy.integrate import solve_ivp
import mpmath as mp
import sympy as sp
mp.mp.dps=100
base=dict(omegaNumerators=[-1,0,1,2],phasePiNumerators=[0,1,2,3],omegaDenominator=1,phasePiDenominator=2,couplingNumerator=3,couplingDenominator=1,timeNumerator=4,timeDenominator=1,integrationSteps=128,sampleSteps=8,referenceWidthNumerator=1,referenceWidthDenominator=1)
specs=[('heterogeneous four',{}),('uncoupled four',dict(couplingNumerator=0)),('identical aligned',dict(omegaNumerators=[1]*4,phasePiNumerators=[0]*4)),('identical antiphase clusters',dict(omegaNumerators=[1]*4,phasePiNumerators=[0,0,2,2])),('identical quarter roots',dict(omegaNumerators=[1]*4)),('antiphase roundoff-sensitive',dict(omegaNumerators=[0,0],phasePiNumerators=[0,1],phasePiDenominator=1,couplingNumerator=16)),('single oscillator',dict(omegaNumerators=[3],phasePiNumerators=[-1],phasePiDenominator=2)),('pair locked from alignment',dict(omegaNumerators=[3,0],phasePiNumerators=[0,0],phasePiDenominator=1,couplingNumerator=5)),('pair drifting',dict(omegaNumerators=[6,0],phasePiNumerators=[0,0],phasePiDenominator=1)),('pair critical from antiphase',dict(omegaNumerators=[1,0],phasePiNumerators=[0,1],phasePiDenominator=1,couplingNumerator=1)),('pair quarter phase',dict(omegaNumerators=[3,0],phasePiNumerators=[0,1],phasePiDenominator=2,couplingNumerator=5)),('same frequency generic phases',dict(omegaNumerators=[1]*4,phasePiNumerators=[0,1,3,7],phasePiDenominator=5)),('perturbed balanced clusters',dict(omegaNumerators=[1]*4,phasePiNumerators=[0,1,1000000000,1000000000],phasePiDenominator=1000000000,couplingNumerator=12,integrationSteps=512)),('regular triangle',dict(omegaNumerators=[1]*3,phasePiNumerators=[0,2,4],phasePiDenominator=3)),('regular five roots',dict(omegaNumerators=[-1]*5,phasePiNumerators=[0,2,4,6,8],phasePiDenominator=5)),('repeated triangle groups',dict(omegaNumerators=[1]*6,phasePiNumerators=[0,0,2,2,4,4],phasePiDenominator=3)),('regular32roots',dict(omegaNumerators=[1]*32,phasePiNumerators=list(range(32)),phasePiDenominator=16,integrationSteps=64)),('heterogeneous8',dict(omegaNumerators=[-3,-2,-1,0,1,2,3,4],phasePiNumerators=[0,1,4,2,6,3,7,5],phasePiDenominator=4)),('heterogeneous32',dict(omegaNumerators=[i%9-4 for i in range(32)],phasePiNumerators=[(7*i)%32 for i in range(32)],phasePiDenominator=16,integrationSteps=256)),('weak coupling',dict(couplingNumerator=1,couplingDenominator=1000000000)),('strong coupling heterogeneous',dict(couplingNumerator=16,integrationSteps=256)),('zero time',dict(timeNumerator=0)),('dense records',dict(sampleSteps=64)),('nondividing record grid',dict(integrationSteps=127,sampleSteps=13)),('rational coefficients',dict(omegaNumerators=[-4,-1,2,7],omegaDenominator=3,phasePiNumerators=[-2,0,3,7],phasePiDenominator=5,couplingNumerator=7,couplingDenominator=3,timeNumerator=7,timeDenominator=3,referenceWidthNumerator=2,referenceWidthDenominator=3)),('negative lifted phases',dict(phasePiNumerators=[-4,-3,-2,-1])),('equivalent phase lifts',dict(phasePiNumerators=[4,5,6,7])),('mean frame shifted',dict(omegaNumerators=[1,2,3,4])),('critical continuum reference',dict(couplingNumerator=2)),('below continuum reference',dict(couplingNumerator=1)),('near above continuum threshold',dict(couplingNumerator=1000000000,couplingDenominator=499999999)),('near below continuum threshold',dict(couplingNumerator=999999999,couplingDenominator=500000000)),('coarse insufficient grid',dict(couplingNumerator=16,integrationSteps=1,sampleSteps=1)),('tiny physical time',dict(timeNumerator=1,timeDenominator=1000000000)),('aligned but different frequencies',dict(phasePiNumerators=[0]*4)),('zero all frequencies generic phases',dict(omegaNumerators=[0]*4,phasePiNumerators=[0,1,3,7],phasePiDenominator=5))]
specs.extend([('continuum rounded equality above',dict(couplingNumerator=499999999,couplingDenominator=500000000,referenceWidthNumerator=499999998,referenceWidthDenominator=999999998)),('continuum rounded equality below',dict(couplingNumerator=499999998,couplingDenominator=499999999,referenceWidthNumerator=499999999,referenceWidthDenominator=1000000000))])
def root_groups(phases,den):
 offsets=Counter(F(n-phases[0],den)%2 for n in phases);m=len(offsets)
 return m if set(offsets)=={F(2*i,m) for i in range(m)} and len(set(offsets.values()))==1 else None
def orders(theta,h,identity,base):
 z=np.mean(np.exp(1j*h*theta));raw=abs(z)
 if identity is not None and h%identity:return dict(real=0.0,imaginary=0.0,magnitude=0.0,squaredMagnitude=0.0)
 if identity is not None:return dict(real=float(np.cos(h*base)),imaginary=float(np.sin(h*base)),magnitude=1.0,squaredMagnitude=1.0)
 return dict(real=float(z.real),imaginary=float(z.imag),magnitude=float(raw),squaredMagnitude=float(raw*raw))
K,W=sp.symbols('K width',positive=True);mu=K/2-W;r=sp.symbols('r',real=True);flow=mu*r-K*r**3/2;assert sp.simplify(sp.diff(flow,r).subs(r,sp.sqrt(1-2*W/K))+(K-2*W))==0
cases=[];records=0
for label,patch in specs:
 p={**base,**patch};N=len(p['omegaNumerators']);omega=np.array(p['omegaNumerators'],float)/p['omegaDenominator'];theta0=np.array([float(mp.pi*n/p['phasePiDenominator']) for n in p['phasePiNumerators']]);T=F(p['timeNumerator'],p['timeDenominator']);kn=F(p['couplingNumerator'],p['couplingDenominator']);k=float(kn);width=F(p['referenceWidthNumerator'],p['referenceWidthDenominator']);groups=root_groups(p['phasePiNumerators'],p['phasePiDenominator']);identical=len(set(p['omegaNumerators']))==1;rotating=identical and groups is not None;analytic=rotating or not kn
 indices=[i*p['integrationSteps']//p['sampleSteps'] for i in range(p['sampleSteps']+1)];tq=[T*F(i,p['integrationSteps']) for i in indices];times=np.array([float(t) for t in tq]);rhs=lambda t,y:omega+k*np.imag(np.mean(np.exp(1j*y))*np.exp(-1j*y))
 if not T or analytic:ys=np.array([theta0+omega*t for t in times])
 else:
  sol=solve_ivp(rhs,(0,float(T)),theta0,t_eval=times,method='DOP853',rtol=2.5e-14,atol=1e-14);assert sol.success and sol.y.shape[1]==len(times);ys=sol.y.T
 rows=[]
 for step,(index,t,exact_time,theta) in enumerate(zip(indices,times,tq,ys)):
  identity=groups if rotating or not exact_time else None;velocity=omega if analytic or not exact_time and groups is not None else rhs(t,theta);changes=omega*t if analytic else theta-theta0;avg=None if not exact_time else omega if analytic else changes/t;first=orders(theta,1,identity,theta0[0]+omega[0]*t);second=orders(theta,2,identity,theta0[0]+omega[0]*t);q=velocity-omega
  rows.append(dict(step=step,gridIndex=index,time=float(t),phases=theta.tolist(),phaseChanges=changes.tolist(),velocities=velocity.tolist(),finiteWindowFrequencies=None if avg is None else avg.tolist(),firstHarmonic=first,secondHarmonic=second,meanUnwrappedPhase=float(np.mean(theta)),observedMeanFrequency=float(np.mean(velocity)),instantaneousFrequencySpread=float(np.ptp(velocity)),finiteWindowFrequencySpread=None if avg is None else float(np.ptp(avg)),couplingPotential=float(-k*N*first['squaredMagnitude']/2),instantaneousPotentialDerivative=float(-np.dot(q,velocity)),negativeSquaredCouplingRate=float(-np.dot(q,q)) if identical else None))
 crit=2*width;linear=kn/2-width;above=linear>0;below=linear<0;positive=1-crit/kn if above else None
 continuum=dict(criticalCoupling=str(crit),linearOrderGrowthRateAtZero=str(linear),nonzeroOrderSquared=str(positive) if positive is not None else None,nonzeroOrder=mp.nstr(mp.sqrt(mp.mpf(positive.numerator)/positive.denominator),80) if positive is not None else None,radialDecayRateAtNonzeroOrder=str(2*linear) if above else None,radialRelaxationTimeAtNonzeroOrder=str(1/(2*linear)) if above else None,orderRelaxationTimeBelow=str(-1/linear) if below else None)
 cases.append(dict(label=label,input=p,analytic=bool(analytic),exactRootGroups=groups,expected=dict(populationSize=N,omega=omega.tolist(),initialPhases=theta0.tolist(),history=rows,continuumReference=continuum)))
 records+=len(rows)
parser=argparse.ArgumentParser();parser.add_argument('--output',required=True);args=parser.parse_args();path=Path(args.output);path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps({'provenance':'Independent SciPy DOP853 with complex mean-field RHS, rtol2.5e-14/atol1e-14. Exact Fraction regular-root identity branches and uncoupled rotations. Production uses pairwise RK4 refinement and is not imported. Continuum branches use Fraction/mpmath100digits plus SymPy linearization identity; these are separate from finite-N numeric references.','cases':cases},indent=2)+'\n');print(json.dumps({'preparations':len(cases),'timeRecords':records,'solver':'independent-complex-mean-field-DOP853'}))
